={{ {
  model: "openai/gpt-oss-120b",
  temperature: 0,
  messages: [
    { role: "system", content: "Extract campaign parameters from the user's request. Use only what the user states. Use null or an empty array for anything not stated. task_category: B2B_LEAD_GEN for finding companies/clients, TALENT_RECRUITMENT for finding people seeking AI/ML/automation roles, otherwise CUSTOM_RESEARCH. company_size_range must be one of the enum values; use ALL if not stated. For TALENT_RECRUITMENT, target_roles must be the role or skill being sought (for example \"AI automation intern\"), never who the person is (never \"student\" or \"fresher\"). Output JSON only." },
    { role: "user", content: $json.campaign_prompt }
  ],
  response_format: { type: "json_schema", json_schema: { name: "campaign_parse", strict: true, schema: {
    type: "object", additionalProperties: false,
    required: ["task_category","target_industry","target_geography","company_size_range","target_roles","exclusion_keywords","max_leads_limit","min_lead_score"],
    properties: {
      task_category: { type: "string", enum: ["B2B_LEAD_GEN","TALENT_RECRUITMENT","CUSTOM_RESEARCH"] },
      target_industry: { type: ["string","null"] },
      target_geography: { type: ["string","null"] },
      company_size_range: { type: "string", enum: ["1-10","11-50","51-200","201-500","501+","ALL"] },
      target_roles: { type: "array", items: { type: "string" } },
      exclusion_keywords: { type: "array", items: { type: "string" } },
      max_leads_limit: { type: ["integer","null"] },
      min_lead_score: { type: ["integer","null"] }
    }
  } } }
} }}

parameters.jsCode:
const ROLE_DEFAULTS = {
  B2B_LEAD_GEN: ["Founder", "CEO", "CTO", "Business Development Director"],
  TALENT_RECRUITMENT: ["AI Automation Intern", "AI Engineer Intern"],
  CUSTOM_RESEARCH: ["Founder"]
};

const SIZES = ["1-10", "11-50", "51-200", "201-500", "501+", "ALL"];

const titleCase = (value) =>
  String(value)
    .replace(/\s+/g, " ")
    .trim()
    .split(" ")
    .filter(Boolean)
    .map((word) =>
      word.length <= 3 && word === word.toUpperCase()
        ? word
        : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
    )
    .join(" ");

const prompt = $("Intake Form").first().json.campaign_prompt;

// 0. Reject empty prompts (ERR_EMPTY_PROMPT)
if (!prompt || !String(prompt).trim()) {
  return [
    {
      json: {
        config_valid: false,
        config_errors: ["ERR_EMPTY_PROMPT"],
        source_prompt: prompt || ""
      }
    }
  ];
}

// 1. Parse model output safely
let p;

try {
  const content = $input.first()?.json?.choices?.[0]?.message?.content;

  if (typeof content !== "string" || !content.trim()) {
    throw new Error("Missing or empty model response content");
  }

  const txt = content
    .replace(/```(?:json)?/gi, "")
    .trim();

  p = JSON.parse(txt);

  if (!p || typeof p !== "object" || Array.isArray(p)) {
    throw new Error("Model response must be a JSON object");
  }
} catch (e) {
  return [
    {
      json: {
        config_valid: false,
        config_errors: ["ERR_PARSE_FAILED: " + e.message],
        source_prompt: prompt
      }
    }
  ];
}

const errors = [];
const clamped = [];

// 2. Validate category
const category = p.task_category;

if (!Object.prototype.hasOwnProperty.call(ROLE_DEFAULTS, category)) {
  errors.push("ERR_BAD_CATEGORY");
}

// 3. Validate and clamp bounds (FR-02)
let max = Number.isInteger(p.max_leads_limit)
  ? p.max_leads_limit
  : 20;

if (max > 100) {
  max = 100;
  clamped.push("max_leads_limit");
}

if (max < 1) {
  max = 1;
  clamped.push("max_leads_limit");
}

let minScore = Number.isInteger(p.min_lead_score)
  ? p.min_lead_score
  : 80;

if (minScore > 100) {
  minScore = 100;
  clamped.push("min_lead_score");
}

if (minScore < 1) {
  minScore = 1;
  clamped.push("min_lead_score");
}

// 4. Apply defaults and normalize values
const industry = titleCase(
  p.target_industry || "Information Technology Services"
);

const geography = titleCase(
  p.target_geography || "India"
);

let size = SIZES.includes(p.company_size_range)
  ? p.company_size_range
  : "ALL";

if (category === "B2B_LEAD_GEN" && size === "ALL") {
  size = "11-50";
}

const rawRoles = Array.isArray(p.target_roles)
  ? p.target_roles
  : [];

let roles = rawRoles
  .map((role) => titleCase(role))
  .filter(Boolean);

// Track B: remove persona-only words for talent recruitment
const PERSONA = new Set([
  "student",
  "students",
  "fresher",
  "freshers",
  "candidate",
  "candidates",
  "people",
  "person",
  "developer",
  "developers",
  "intern",
  "interns"
]);

if (category === "TALENT_RECRUITMENT") {
  roles = roles.filter(
    (role) => !PERSONA.has(role.toLowerCase())
  );
}

// Use category defaults if no valid roles remain
if (roles.length === 0 && ROLE_DEFAULTS[category]) {
  roles = [...ROLE_DEFAULTS[category]];
}

// Normalize exclusion keywords
const rawExclusions = Array.isArray(p.exclusion_keywords)
  ? p.exclusion_keywords
  : [];

const exclusions = [
  ...new Set(
    rawExclusions
      .map((item) => String(item).trim().toLowerCase())
      .filter(Boolean)
  )
];

// 5. Check contradictions (FR-02)
for (const exclusion of exclusions) {
  const industryConflict = industry
    .toLowerCase()
    .includes(exclusion);

  const roleConflict = roles.some((role) =>
    role.toLowerCase().includes(exclusion)
  );

  if (industryConflict || roleConflict) {
    errors.push(
      `ERR_CONTRADICTION: exclusion "${exclusion}" overlaps target industry/roles`
    );
  }
}

// 6. Compile search queries (FR-03)
let compiled = [];

if (category === "B2B_LEAD_GEN") {
  compiled = [
    `"web development agency" ${geography} founder -site:linkedin.com -site:naukri.com -site:clutch.co`,
    `"software development company" ${geography} "our team" founder -site:linkedin.com -site:clutch.co`
  ];
} else if (category === "TALENT_RECRUITMENT") {
  // Candidate-intent phrasing; role filtering occurs during extraction/scoring.
  compiled = [
    `site:reddit.com (intitle:"looking for internship" OR intitle:"seeking internship" OR intitle:"open to work" OR intitle:"for hire" OR intitle:"my portfolio") (AI OR automation OR n8n OR "machine learning")`
  ];
} else {
  compiled = [
    `"${industry}" "${geography}"`
  ];
}

// 7. Generate deterministic campaign ID
// Case- and role-order-insensitive
const core = {
  category,
  industry: industry.toLowerCase(),
  geography: geography.toLowerCase(),
  size,
  roles: roles.map((role) => role.toLowerCase()).sort(),
  exclusions: [...exclusions].sort(),
  max,
  minScore
};

let h = 5381;

for (const ch of JSON.stringify(core)) {
  h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0;
}

const campaign_id =
  `CMP-${new Date().getFullYear()}-${h
    .toString(36)
    .toUpperCase()
    .padStart(4, "0")
    .slice(-4)}`;

if (!/^CMP-[0-9]{4}-[A-Z0-9]{4}$/.test(campaign_id)) {
  errors.push("ERR_BAD_CAMPAIGN_ID");
}

// 8. Return normalized campaign configuration
return [
  {
    json: {
      campaign_id,
      task_category: category,
      target_industry: industry,
      target_geography: geography,
      company_size_range: size,
      target_roles: roles,
      exclusion_keywords: exclusions,
      max_leads_limit: max,
      min_lead_score: minScore,
      compiled_queries: compiled,
      clamped_fields: [...new Set(clamped)],
      config_valid: errors.length === 0,
      config_errors: errors,
      source_prompt: prompt,
      created_at: new Date().toISOString()
    }
  }
];

const cfg = $input.first().json;
const MAX_PAGES = 1; // dev: 1 page per query. Never 5 on the free plan.
const out = [];
for (const q of cfg.compiled_queries) {
  for (let page = 0; page < MAX_PAGES; page++) {
    out.push({ json: {
      campaign_id: cfg.campaign_id,
      task_category: cfg.task_category,
      query: q,
      start: page * 10,
      max_leads_limit: cfg.max_leads_limit
    } });
  }
}
return out;

const BLOCK = ['linkedin.com','facebook.com','twitter.com','x.com','instagram.com','youtube.com','wikipedia.org','glassdoor.com','indeed.com','naukri.com','justdial.com','ambitionbox.com','crunchbase.com','scribd.com','goodfirms.co','builtinpune.in','clutch.co','sulekha.com','indiamart.com','quora.com','medium.com','reddit.com','trustpilot.com','g2.com','topdevelopers.co','designrush.com','softwaresuggest.com','techbehemoths.com','startupintros.com'];
const LIST_TITLE = /\b(list of|reviews?|directory)\b|\bcompanies\b|\b(top|best)\s+\d+/i;
const cfg = $('Split Queries').first().json;
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return h.toString(36); };
const seen = new Set(), out = [], skipLog = [];
let errors = 0;

for (const item of $input.all()) {
  if (item.json.error || !Array.isArray(item.json.organic_results)) { errors++; continue; }
  const query = item.json.search_parameters?.q || '';
  for (const r of item.json.organic_results) {
    const m = String(r.link || '').match(/^(https?):\/\/([^\/?#:]+)/i);
    if (!m) { skipLog.push({ link: r.link, reason: 'BAD_URL' }); continue; }
    const host = m[2].toLowerCase().replace(/^www\./, '');
    if (BLOCK.some(b => host === b || host.endsWith('.' + b))) { skipLog.push({ link: r.link, reason: 'BLOCKED_DOMAIN' }); continue; }
    if (LIST_TITLE.test(r.title || '')) { skipLog.push({ link: r.link, reason: 'LIST_TITLE' }); continue; }
    if (seen.has(host)) { skipLog.push({ link: r.link, reason: 'DUPLICATE_DOMAIN' }); continue; }
    seen.add(host);
    out.push({ json: {
      result_id: 'RES-' + hash(host),
      campaign_id: cfg.campaign_id,
      source_url: r.link,
      normalized_domain: host,
      source_platform: 'google_serp',
      title: r.title || null,
      snippet: r.snippet || null,
      query,
      discovery_time: new Date().toISOString(),
      scrape_status: 'PENDING'
    } });
    if (out.length >= cfg.max_leads_limit) break;
  }
}
if (out.length === 0) return [{ json: { no_hits: true, errors, skipped: skipLog.length, skip_log: skipLog, campaign_id: cfg.campaign_id } }];
return out;

const cfg = $('Split Queries').first().json;
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const hash = s => { let h = 5381; for (const c of s) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return h.toString(36); };
const POST_URL = /^https?:\/\/(?:www\.|old\.)?reddit\.com\/r\/([^\/?#]+)\/comments\/([a-z0-9]+)/i;
const EMPLOYER = /^\W*(we('|\u2019)re |we are )?(hiring|looking for (an?|the|our) )/i;
const JUNIOR = /\b(student|intern|internship|fresher|entry[- ]level|junior|beginner|learning|my portfolio)\b/i;
const SENIOR = /for hire|\$\s?\d+[^\s]*\s?\/\s?hr|\b\d+\+?\s*years\b|\bsenior\b|\bspecialist\b/i;

const seen = new Set(), out = [], skipLog = [];
let errors = 0;

for (const item of $input.all()) {
  if (item.json.error || !Array.isArray(item.json.organic_results)) { errors++; continue; }
  const query = item.json.search_parameters?.q || '';
  for (const r of item.json.organic_results) {
    const m = String(r.link || '').match(POST_URL);
    if (!m) { skipLog.push({ link: r.link, reason: 'NOT_A_POST_URL' }); continue; }
    const title = r.title || '';
    if (EMPLOYER.test(title)) { skipLog.push({ link: r.link, reason: 'EMPLOYER_POST' }); continue; }
    const key = norm(title);
    if (!key || seen.has(key)) { skipLog.push({ link: r.link, reason: 'DUPLICATE_TITLE' }); continue; }
    seen.add(key);
    // Title-only hint: Google snippets can be comment text, so they are not used here
    const text = title;
    const level = JUNIOR.test(text) ? 'STUDENT_OR_JUNIOR' : (SENIOR.test(text) ? 'EXPERIENCED' : 'UNCLEAR');
    out.push({ json: {
      result_id: 'RES-' + hash(key),
      campaign_id: cfg.campaign_id,
      source_url: r.link,
      normalized_domain: 'reddit.com',
      source_platform: 'reddit',
      subreddit: m[1],
      post_id: m[2],
      title: title || null,
      snippet: r.snippet || null,
      candidate_level_hint: level,
      query,
      discovery_time: new Date().toISOString(),
      scrape_status: 'PENDING'
    } });
    if (out.length >= cfg.max_leads_limit) break;
  }
}
if (out.length === 0) return [{ json: { no_hits: true, errors, skipped: skipLog.length, skip_log: skipLog, campaign_id: cfg.campaign_id } }];
return out;

const hits = $('Extract Hits').all();
const out = [];
const NAMED = { nbsp:' ', amp:'&', lt:'<', gt:'>', quot:'"', apos:"'", times:'x', copy:'(c)', reg:'(R)', ndash:'-', mdash:'-', hellip:'...', rsquo:"'", lsquo:"'", ldquo:'"', rdquo:'"' };
const decode = s => s
  .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(parseInt(d, 10)))
  .replace(/&([a-z]+);/gi, (m, n) => (NAMED[n.toLowerCase()] !== undefined ? NAMED[n.toLowerCase()] : m))
  .replace(/\u00a0/g, ' ');

$input.all().forEach((item, i) => {
  const hit = hits[i] ? hits[i].json : {};
  const status = item.json.statusCode || item.json.status || null;
  const body = typeof item.json.body === 'string' ? item.json.body : (typeof item.json.data === 'string' ? item.json.data : '');
  const base = { ...hit, http_status: status };

  if (item.json.error || !body || (status && status >= 400)) {
    out.push({ json: { ...base, scrape_status: 'SCRAPE_FAILED', scrape_error: String(item.json.error?.message || item.json.error || ('HTTP ' + status)), page_text: '' } });
    return;
  }

  const emailObfuscated = /cdn-cgi\/l\/email-protection|\[email(?:&#160;|&nbsp;|\s)protected\]/i.test(body);

  let t = body
    .replace(/<(script|style|noscript|svg|iframe)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(br|\/p|\/div|\/li|\/h[1-6]|\/tr)\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  t = decode(t).replace(/[ \t\r\f\v]+/g, ' ').replace(/\s*\n\s*/g, '\n').replace(/\n{2,}/g, '\n').trim();

  if (t.length < 200) {
    out.push({ json: { ...base, scrape_status: 'SCRAPE_EMPTY', scrape_error: 'Too little text (client-side rendered?)', page_text: t, email_obfuscated: emailObfuscated } });
    return;
  }
  // Exactly 12,000 chars: 8,000 head + 7-char marker + 3,993 tail (contact details are usually in the footer)
  const capped = t.length > 12000 ? t.slice(0, 8000) + '\n[...]\n' + t.slice(-3993) : t;
  out.push({ json: { ...base, scrape_status: 'SCRAPED', page_text: capped, page_text_chars: capped.length, text_source: 'page', email_obfuscated: emailObfuscated } });
});
return out;

return $input.all().map(i => {
  const j = i.json;
  if (j.no_hits) return i;
  const text = `${j.title || ''}\n${j.snippet || ''}`.trim();
  return { json: { ...j, scrape_status: 'SERP_ONLY', page_text: text, page_text_chars: text.length, text_source: 'serp_title_snippet' } };
});

const KEY = /(founder|co-founder|ceo|cto|chief|director|managing|president|head of|owner|contact|email|e-mail|@|employees|team of|headquarter|head office|located|address|hq\b|india)/i;
return $input.all().map(i => {
  const j = i.json;
  if (j.scrape_status !== 'SCRAPED' && j.scrape_status !== 'SERP_ONLY') return i;
  const lines = String(j.page_text || '').split('\n').map(s => s.trim()).filter(Boolean);
  let ctx;
  if (j.scrape_status === 'SERP_ONLY') {
    ctx = String(j.page_text || '').slice(0, 1500);
  } else {
    const head = [...new Set(lines.slice(0, 25))].join('\n');
    const tail = [...new Set(lines.slice(-30))].join('\n');
    const signal = [...new Set(lines.slice(25).filter(l => KEY.test(l) && l.length < 300))].slice(0, 30).join('\n');
    const body = (head + '\n---\n' + tail + '\n---\n' + signal).slice(0, 4000);
    ctx = `SEARCH RESULT TITLE: ${j.title || ''}\nSEARCH RESULT SNIPPET: ${j.snippet || ''}\n---\n` + body;
  }
  return { json: { ...j, llm_context: ctx, llm_context_chars: ctx.length } };
});

parameters.jsonBody:
={{ {
  model: "openai/gpt-oss-120b",
  temperature: 0,
  messages: [
    { role: "system", content: "You extract company facts from website text. Rules: 1) Use ONLY the provided text. 2) If a field is not explicitly stated, return null (or UNKNOWN for estimated_employee_range, LOW for confidence_level). Never guess. 3) Copy an email only if it appears character-for-character in the text; never construct one. 4) extracted_evidence_snippets: verbatim sentences copied exactly from the text supporting industry or role claims, max 3. 5) If the text is not a company website (error page, directory, parked domain), set extraction_successful=false. 6) estimated_employee_range and confidence_level must never be null. 7) headquarters_location: use only if the text says headquarters, head office, HQ, or (HQ) next to an address; a landing-page title like 'IT company in Pune' is not a headquarters. Otherwise null. 8) company_contact_email: a general company inbox (info@, contact@, business@, sales@) copied character-for-character from the text; null if none. Never put a generic inbox in public_business_email. 9) Output JSON only." },
    { role: "user", content: $json.llm_context }
  ],
  response_format: { type: "json_schema", json_schema: { name: "lead_extraction", strict: true, schema: {
    type: "object", additionalProperties: false,
    required: ["extraction_successful","company_name","official_website","industry_sector","headquarters_location","company_description","estimated_employee_range","key_decision_maker","extracted_evidence_snippets","confidence_level","company_contact_email"],
    properties: {
      extraction_successful: { type: "boolean" },
      company_name: { type: ["string","null"] },
      official_website: { type: ["string","null"] },
      industry_sector: { type: ["string","null"] },
      headquarters_location: { type: ["string","null"] },
      company_description: { type: ["string","null"] },
      estimated_employee_range: { type: "string", enum: ["1-10","11-50","51-200","201-500","501+","UNKNOWN"] },
      key_decision_maker: { type: "object", additionalProperties: false,
        required: ["full_name","designation","public_business_email","linkedin_profile_url"],
        properties: { full_name: { type: ["string","null"] }, designation: { type: ["string","null"] }, public_business_email: { type: ["string","null"] }, linkedin_profile_url: { type: ["string","null"] } } },
      extracted_evidence_snippets: { type: "array", items: { type: "string" } },
      confidence_level: { type: "string", enum: ["HIGH","MEDIUM","LOW"] },
      company_contact_email: { type: ["string","null"] }
    }
  } } }
} }}

parameters.jsCode:
const src = $('Build LLM Context').all().filter(i => i.json.llm_context);
const out = [];
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const isSentence = q => /[.!?]$/.test(norm(q)) && norm(q).split(' ').length >= 5;
const BOILERPLATE = /all rights reserved|privacy policy|cookie|terms (&|and) conditions|copyright/i;

$input.all().forEach((item, idx) => {
  const s = src[idx] ? src[idx].json : {};
  let o;
  try {
    const content = item.json?.choices?.[0]?.message?.content;
    if (!content) throw new Error(item.json?.error?.message || 'NO_GROQ_RESPONSE');
    const txt = content.replace(/```json|```/g, '').trim();
    o = JSON.parse(txt);
  } catch (e) {
    const msg = String(item.json?.error?.message || e.message);
    out.push({ json: { ...s, extraction_status: 'EXTRACTION_FAILED', extraction_error: msg, retryable: /socket|TLS|ECONN|ETIMEDOUT|429|50\d/i.test(msg) } });
    return;
  }
  const hay = String(s.llm_context || '') + ' ' + String(s.page_text || '');
  const text = norm(hay);
  const flags = [];

  const snippets = (o.extracted_evidence_snippets || []).filter(q => {
    const ok = isSentence(q) && !BOILERPLATE.test(q) && text.includes(norm(q));
    if (!ok) flags.push('DROPPED_UNVERIFIED_SNIPPET');
    return ok;
  });

  const dm = o.key_decision_maker || {};
  let email = dm.public_business_email || null;
  if (email && !hay.toLowerCase().includes(email.toLowerCase())) { flags.push('DROPPED_UNVERIFIED_EMAIL'); email = null; }

  let name = dm.full_name || null;
  if (name && !text.toLowerCase().includes(norm(name).toLowerCase())) { flags.push('DROPPED_UNVERIFIED_NAME'); name = null; }

  let cemail = o.company_contact_email || null;
  if (cemail && !hay.toLowerCase().includes(cemail.toLowerCase())) { flags.push('DROPPED_UNVERIFIED_EMAIL'); cemail = null; }
  // Never trust model self-rated confidence: derive a cap from what was actually verified
let conf = o.confidence_level;
const verifiedFacts = [!!name, !!email, o.estimated_employee_range !== 'UNKNOWN', snippets.length >= 2].filter(Boolean).length;
if (verifiedFacts < 2) conf = 'LOW';
else if (verifiedFacts < 3 && conf === 'HIGH') conf = 'MEDIUM';

  out.push({ json: {
    ...s,
    extraction_status: 'EXTRACTED',
    extraction_successful: !!o.extraction_successful,
    company_name: o.company_name,
    official_website: 'https://' + (s.normalized_domain || ''),
    industry_sector: o.industry_sector,
    headquarters_location: o.headquarters_location,
    company_description: o.company_description,
    estimated_employee_range: o.estimated_employee_range,
    key_decision_maker: { full_name: name, designation: name ? dm.designation : null, public_business_email: email, linkedin_profile_url: null },
    company_contact_email: cemail,
    extracted_evidence_snippets: snippets,
    confidence_level: conf,
    verification_flags: flags
  } });
});
return out;

const PARKED = /(this domain (is|may be) for sale|domain (is )?parked|buy this domain|account suspended|coming soon|under construction|page not found|access denied|just a moment|enable javascript|404 not found)/i;
return $input.all().map(i => {
  const j = i.json;
  if (j.scrape_status !== 'SCRAPED') return i;
  const t = String(j.page_text || '');
  if (t.length < 400 && PARKED.test(t)) {
    return { json: { ...j, scrape_status: 'PAGE_UNUSABLE', scrape_error: 'PARKED_OR_ERROR_PAGE' } };
  }
  return i;
});

parameters.jsonBody:
={{ {
  model: "openai/gpt-oss-20b",
  temperature: 0,
  messages: [
