const src = $('Needs Retry?').all();
const out = [];
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const isSentence = q => /[.!?]$/.test(norm(q)) && norm(q).split(' ').length >= 5;
const BOILERPLATE = /all rights reserved|privacy policy|cookie|terms (&|and) conditions|copyright/i;

$input.all().forEach((item, idx) => {
  const s = src[idx] ? src[idx].json : {};
  let o;
  try {
    const content = item.json?.choices?.[0]?.message?.content;
    if (!content) throw new Error(item.json?.error?.message || 'NO_GROQ_RESPONSE');
    const txt = content.replace(/```json|```/g, '').trim();
    o = JSON.parse(txt);
  } catch (e) {
    const msg = String(item.json?.error?.message || e.message);
    out.push({ json: { ...s, extraction_status: 'EXTRACTION_FAILED', extraction_error: msg, retryable: /socket|TLS|ECONN|ETIMEDOUT|429|50\d/i.test(msg) } });
    return;
  }
  const hay = String(s.llm_context || '') + ' ' + String(s.page_text || '');
  const text = norm(hay);
  const flags = [];

  const snippets = (o.extracted_evidence_snippets || []).filter(q => {
    const ok = isSentence(q) && !BOILERPLATE.test(q) && text.includes(norm(q));
    if (!ok) flags.push('DROPPED_UNVERIFIED_SNIPPET');
    return ok;
  });

  const dm = o.key_decision_maker || {};
  let email = dm.public_business_email || null;
  if (email && !hay.toLowerCase().includes(email.toLowerCase())) { flags.push('DROPPED_UNVERIFIED_EMAIL'); email = null; }

  let name = dm.full_name || null;
  if (name && !text.toLowerCase().includes(norm(name).toLowerCase())) { flags.push('DROPPED_UNVERIFIED_NAME'); name = null; }

  let cemail = o.company_contact_email || null;
  if (cemail && !hay.toLowerCase().includes(cemail.toLowerCase())) { flags.push('DROPPED_UNVERIFIED_EMAIL'); cemail = null; }
  // Never trust model self-rated confidence: derive a cap from what was actually verified
let conf = o.confidence_level;
const verifiedFacts = [!!name, !!email, o.estimated_employee_range !== 'UNKNOWN', snippets.length >= 2].filter(Boolean).length;
if (verifiedFacts < 2) conf = 'LOW';
else if (verifiedFacts < 3 && conf === 'HIGH') conf = 'MEDIUM';

  out.push({ json: {
    ...s,
    model_used: 'gpt-oss-20b',
    extraction_status: 'EXTRACTED',
    retryable: false,
    extraction_successful: !!o.extraction_successful,
    company_name: o.company_name,
    official_website: 'https://' + (s.normalized_domain || ''),
    industry_sector: o.industry_sector,
    headquarters_location: o.headquarters_location,
    company_description: o.company_description,
    estimated_employee_range: o.estimated_employee_range,
    key_decision_maker: { full_name: name, designation: name ? dm.designation : null, public_business_email: email, linkedin_profile_url: null },
    company_contact_email: cemail,
    extracted_evidence_snippets: snippets,
    confidence_level: conf,
    verification_flags: flags
  } });
});
return out;

const cfg = $('Parameter Normalizer').first().json;
const FREE = ['gmail.com','yahoo.com','hotmail.com','outlook.com','aol.com','proton.me','protonmail.com','icloud.com','rediffmail.com'];
const GENERIC = /^(info|contact|business|sales|support|hello|admin|office|enquiry|inquiry|finance|hr|careers|jobs|whistleblower|marketing|accounts|billing|help|team|mail|webmaster)([._+-]|@)/i;
const RFC = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const hostOf = u => { const m = String(u || '').match(/^(?:https?:\/\/)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };

return $input.all().map(item => {
  const e = item.json;
  const errors = [];
  const out = { ...e };

  // 1. Structural gate (fallback-model items are gated on company_name)
  const usable = e.extraction_status === 'EXTRACTED' && !!e.company_name && (e.extraction_successful || e.model_used);
  if (!usable) {
    return { json: { ...out, validation_status: 'REJECTED', rejection_reason: e.extraction_status === 'EXTRACTED' ? 'ERR_EMPTY_EXTRACTION' : 'ERR_NOT_EXTRACTED', rejection_veto: true } };
  }

  // 2. Domain from the scraped URL (never from the model)
  const domain = hostOf(e.source_url) || e.normalized_domain || '';
  if (!domain || !/\.[a-z]{2,}$/i.test(domain)) {
    return { json: { ...out, validation_status: 'REJECTED', rejection_reason: 'ERR_MALFORMED_URL', rejection_veto: true } };
  }
  out.normalized_domain = domain;

  // 3. Exclusion veto
  const hay = ((e.company_name || '') + ' ' + (e.company_description || '') + ' ' + (e.industry_sector || '')).toLowerCase();
  const hit = (cfg.exclusion_keywords || []).find(x => x && hay.includes(String(x).toLowerCase()));
  if (hit) {
    return { json: { ...out, validation_status: 'REJECTED', rejection_reason: 'VETO_EXCLUSION: ' + hit, rejection_veto: true } };
  }

  // 4. Email classification (decision maker first, then company inbox)
  const dm = e.key_decision_maker || {};
  const rawEmail = (dm.public_business_email || e.company_contact_email || '').trim();
  let verified_email = null, email_status = 'UNAVAILABLE';
  if (rawEmail) {
    if (!RFC.test(rawEmail) || /\.\./.test(rawEmail)) { email_status = 'INVALID_SYNTAX'; }
    else {
      verified_email = rawEmail;
      const edomain = rawEmail.split('@')[1].toLowerCase();
      if (FREE.includes(edomain)) email_status = 'FREE_WEBMAIL';
      else if (GENERIC.test(rawEmail)) email_status = 'GENERIC_INBOX';
      else email_status = 'SYNTAX_VALID';
      if (!/(^|\.)/.test(edomain) || (edomain !== domain && !edomain.endsWith('.' + domain) && !domain.endsWith('.' + edomain))) {
        if (email_status === 'SYNTAX_VALID') email_status = 'DOMAIN_MISMATCH';
      }
    }
  }

  // 5. Decision maker counts only when a verbatim quote supports the designation
  const quotes = (e.extracted_evidence_snippets || []).join(' ').toLowerCase();
  const desig = String(dm.designation || '').toLowerCase();
  const dm_supported = !!(dm.full_name && desig && quotes.includes(String(dm.full_name).toLowerCase()) && quotes.includes(desig));

  return { json: {
    ...out,
    validation_status: 'VALIDATED',
    verified_email, email_status,
    decision_maker_supported: dm_supported,
    evidence_count: (e.extracted_evidence_snippets || []).length,
    validation_errors: errors,
    validated_at: new Date().toISOString()
  } };
});

const cfg = $('Parameter Normalizer').first().json;
const lc = s => String(s || '').toLowerCase();
const SENIOR = /(founder|co-founder|ceo|cto|chief|managing director|president|owner|vp|vice president|director)/i;

return $input.all().map(item => {
  const e = item.json;

  if (e.validation_status !== 'VALIDATED') {
    return { json: { ...e, lead_score: 0, sub_scores: {}, routing_target: 'QUARANTINE', score_reason: e.rejection_reason || 'NOT_VALIDATED' } };
  }

  const dm = e.key_decision_maker || {};

  // Industry (30%): 100 direct match, 50 adjacent tech, 0 mismatch
  const ind = lc(e.industry_sector + ' ' + e.company_description);
  const target = lc(cfg.target_industry);
  const words = target.split(/\s+/).filter(w => w.length > 3);
  const direct = ind.includes(target) || (words.length && words.every(w => ind.includes(w))) || /\bit services\b|software|technology|digital|web development/.test(ind);
  const s_ind = direct ? 100 : (/(tech|data|cloud|ai|automation)/.test(ind) ? 50 : 0);

  // ICP size (20%): 100 matches target, 50 unknown, 0 enterprise or solo
  const size = e.estimated_employee_range;
  let s_icp;
  if (cfg.company_size_range !== 'ALL' && size === cfg.company_size_range) s_icp = 100;
  else if (size === 'UNKNOWN') s_icp = 50;
  else if (size === '501+' || size === '1-10') s_icp = 0;
  else s_icp = 50;

  // Geography (15%): 100 HQ in target, 50 regional office, 0 foreign
  const geo = lc(cfg.target_geography);
  const hq = lc(e.headquarters_location);
  const indiaWords = /india|gujarat|maharashtra|pune|mumbai|bengaluru|bangalore|delhi|hyderabad|chennai|ahmedabad|punjab/;
  let s_geo;
  if (!hq) s_geo = 50;
  else if (hq.includes(geo) || (geo === 'india' && indiaWords.test(hq))) s_geo = 100;
  else if (indiaWords.test(hq)) s_geo = 50;
  else s_geo = 0;

  // Decision maker (15%): 100 supported senior, 50 supported other, 0 none or unsupported
  let s_role = 0;
  if (e.decision_maker_supported) s_role = SENIOR.test(dm.designation || '') ? 100 : 50;

  // Evidence (20%): 100 for 2 or more verified quotes, 50 for one, 0 for none
  const n = e.evidence_count || 0;
  const s_evid = n >= 2 ? 100 : (n === 1 ? 50 : 0);

  const lead_score = Math.round(0.30 * s_ind + 0.20 * s_icp + 0.15 * s_geo + 0.15 * s_role + 0.20 * s_evid);
  const routing_target = lead_score >= cfg.min_lead_score ? 'MASTER' : (lead_score >= 60 ? 'REVIEW' : 'QUARANTINE');

  return { json: { ...e, lead_score, sub_scores: { industry: s_ind, icp: s_icp, geography: s_geo, role: s_role, evidence: s_evid }, routing_target } };
});

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

// Hash: try SHA-256, fall back to a deterministic pure-JS hash
function hashOf(s) {
  try {
    const c = require('crypto');
    return 'sha256:' + c.createHash('sha256').update(s).digest('hex').slice(0, 32);
  } catch (e) {
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return 'h64:' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
  }
}

// Normalize: lowercase, strip www, strip common subdomains and country-level duplicates
function canonicalDomain(d) {
  let x = String(d || '').toLowerCase().trim().replace(/^www\./, '');
  x = x.replace(/^(m|mobile|portal|app|web|en|in)\./, '');
  return x;
}

const batchSeen = new Set();
return $input.all().map(item => {
  const e = item.json;
  const domain = canonicalDomain(e.normalized_domain);
  if (!domain) return { json: { ...e, dedup_status: 'NO_DOMAIN' } };
  const key = hashOf(domain);
  const emailKey = e.verified_email ? hashOf(String(e.verified_email).toLowerCase()) : null;

  const dupInRun = batchSeen.has(key);
  const dupAcross = !!staticData.seen[key];
  batchSeen.add(key);

  if (dupInRun || dupAcross) {
    return { json: { ...e, domain_hash: key, dedup_status: dupAcross ? 'DUPLICATE_PREVIOUS_RUN' : 'DUPLICATE_IN_RUN', routing_target: 'DUPLICATE', first_seen_at: staticData.seen[key] || null } };
  }
  // Register only leads that will be stored (not quarantine vetoes with no value)
  staticData.seen[key] = new Date().toISOString();
  return { json: { ...e, domain_hash: key, email_hash: emailKey, normalized_domain: domain, dedup_status: 'NEW' } };
});

const now = new Date().toISOString();
const short = s => String(s || '').slice(0, 40);
return $input.all().map(i => {
  const e = i.json;
  const dm = e.key_decision_maker || {};
  const id = String(e.domain_hash || e.result_id || '').replace(/[^a-z0-9]/gi, '').slice(-10).toUpperCase();
  return { json: {
    ...e,
    review_id: 'REV-' + id, rejection_id: 'REJ-' + id,
    master_lead_id: 'MLD-' + id.slice(0, 4),
    contact_name: dm.full_name || '', designation: dm.designation || '',
    sub_scores_text: JSON.stringify(e.sub_scores || {}),
    evidence_text: (e.extracted_evidence_snippets || []).join(' | '),
    flags_text: (e.verification_flags || []).join(','),
    reason_text: e.score_reason || e.rejection_reason || ('score ' + (e.lead_score ?? 0) + ' below 60'),
    now
  } };
});
